package nl.smartstreamlabs.sbwdroneconfig;
public class MineRoverRenderer extends CachedVehicleRenderer<MineRoverEntity>{
 private static com.atsuishio.superbwarfare.entity.projectile.Blu43Entity display;private static com.atsuishio.superbwarfare.entity.projectile.Tm62Entity tmDisplay;public static void clear(){display=null;tmDisplay=null;}
 public MineRoverRenderer(net.minecraft.client.renderer.entity.EntityRendererProvider.Context c){super(c,new MineRoverModel());}
 @Override public void render(MineRoverEntity e,float yaw,float partial,com.mojang.blaze3d.vertex.PoseStack pose,net.minecraft.client.renderer.MultiBufferSource buffers,int light){super.render(e,yaw,partial,pose,buffers,light);var client=net.minecraft.client.Minecraft.getInstance();if(client.player==null)return;if(java.util.stream.IntStream.range(0,6).anyMatch(i->e.mineKind(i)==1)&&(display==null||display.level()!=e.level()))display=new com.atsuishio.superbwarfare.entity.projectile.Blu43Entity(client.player,e.level());if(java.util.stream.IntStream.range(0,6).anyMatch(i->e.mineKind(i)==2)&&(tmDisplay==null||tmDisplay.level()!=e.level()))tmDisplay=new com.atsuishio.superbwarfare.entity.projectile.Tm62Entity(client.player,e.level(),false);var m=e.getVehicleTransform(partial);pose.pushPose();pose.translate(m.m30()-net.minecraft.util.Mth.lerp(partial,e.xo,e.getX()),m.m31()-net.minecraft.util.Mth.lerp(partial,e.yo,e.getY()),m.m32()-net.minecraft.util.Mth.lerp(partial,e.zo,e.getZ()));pose.mulPose(m.getUnnormalizedRotation(new org.joml.Quaternionf()));for(int i=0;i<6;i++)if(e.loaded(i)){pose.pushPose();pose.translate((i%2==0?4.5:-4.5)/16,23.0/16,0);pose.mulPose(com.mojang.math.Axis.XP.rotationDegrees(18));pose.translate(0,1.05/16,-new double[]{-17,0,17}[i/2]/16);if(e.mineKind(i)==3)Lm01Display.render(pose,buffers,light,e.level(),.7f);else if(e.mineKind(i)==2)client.getEntityRenderDispatcher().getRenderer(tmDisplay).render(tmDisplay,0,0,pose,buffers,light);else client.getEntityRenderDispatcher().getRenderer(display).render(display,0,0,pose,buffers,light);pose.popPose();}pose.popPose();}
}
